"""Kaggle entry point (generated by kaggle/build_kernel.py): GNN LDPC Tuning2 5G.

Embedded: common, normal_ldpc, 5g_ldpc, tradeoffs, tuning, final of the GNN_LDPC_Decoding project.
"""

import base64
import io
import os
import shutil
import subprocess
import sys
import tarfile

BUNDLE = ''
SRC = "/kaggle/working/src"
RUNS = [('tuning/run_tuning.py', ['--part', '5g', '--round', '2'])]

with tarfile.open(fileobj=io.BytesIO(base64.b64decode(BUNDLE)), mode="r:gz") as t:
    t.extractall(SRC, filter="data")
try:
    import pynvml  # noqa: F401
except ImportError:
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", "nvidia-ml-py"], check=False)
if shutil.which("nvidia-smi"):
    subprocess.run(["nvidia-smi"], check=False)
rc = 0
for script, args in RUNS:
    rc |= subprocess.run([sys.executable, os.path.join(SRC, script)] + args).returncode
shutil.rmtree(SRC, ignore_errors=True)
sys.exit(rc)
